implementation:
MotorForward := FALSE;
MotorReverse := FALSE;
kick := FALSE;
CompletionLight := FALSE;


IF Mode <> modePrev THEN
  state := 0;
END_IF
modePrev := Mode;

IF NOT Mode THEN

  IF ForwardButton AND (NOT ReverseButton) THEN
    MotorForward := TRUE;
  END_IF
  IF ReverseButton AND (NOT ForwardButton) THEN
    MotorReverse := TRUE;
  END_IF
ELSE

  CASE state OF
    0:

      IF SensorFeed THEN
        state := 1;
        MotorForward := TRUE;
      END_IF
    1:

      IF SensorWash THEN
        state := 2;
      ELSE
        MotorForward := TRUE;
      END_IF
    2:

      IF washComplete THEN
        state := 3;
        MotorForward := TRUE;
      END_IF
    3:

      IF SensorWeight THEN
        state := 4;
      ELSE
        MotorForward := TRUE;
      END_IF
    4:

      IF weightComplete THEN
        IF (weight >= 100.0) AND (weight <= 200.0) THEN

          firingTemp := 500.0 + (weight - 100.0) * 0.5;
          state := 5;
          MotorForward := TRUE;
        ELSE

          kick := TRUE;
          state := 0;
        END_IF
      END_IF
    5:

      IF SensorFiring THEN
        state := 6;
      ELSE
        MotorForward := TRUE;
      END_IF
    6:

      IF firingComplete THEN
        state := 7;
        MotorForward := TRUE;
      END_IF
    7:

      IF SensorOutput THEN
        state := 8;
        CompletionLight := TRUE;
      ELSE
        MotorForward := TRUE;
      END_IF
    8:

      IF SensorOutput THEN
        CompletionLight := TRUE;
      ELSE
        state := 0;
      END_IF
  ELSE
    state := 0;
  END_CASE
END_IF
